#!/usr/bin/env node

// 本文件是 citizensdk/ci-sdk.yml 的完整动作入口。
// 所需实现内嵌于本文件，运行时不得导入其它产品或动作脚本。
import { mkdtempSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const implementations = Object.freeze({"dependencies":"#!/usr/bin/env node\n\n// 全仓依赖检查只读取受 Git 管理的 manifest、lockfile、工具链和 workflow；\n// 更新必须由人工明确执行并经过产品真实验收，CI/Release 不得自动改写依赖。\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { spawnSync } from \"node:child_process\";\nimport { dirname, resolve } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst repositoryRoot = process.env.GMB_REPOSITORY_ROOT || process.cwd();\nconst contractPath = resolve(repositoryRoot, \".github/dependencies.json\");\nconst contract = JSON.parse(readFileSync(contractPath, \"utf8\"));\nconst [command = \"check\", ...argumentsList] = process.argv.slice(2);\nconst scopeIndex = argumentsList.indexOf(\"--scope\");\nconst scopeName = scopeIndex >= 0 ? argumentsList[scopeIndex + 1] : \"repository\";\nconst shaPattern = /^[0-9a-f]{40}$/;\n\nfunction fail(message) {\n  throw new Error(message);\n}\n\nfunction pathFor(relativePath) {\n  return resolve(repositoryRoot, relativePath);\n}\n\nfunction read(relativePath) {\n  const absolutePath = pathFor(relativePath);\n  if (!existsSync(absolutePath)) {\n    fail(`缺少依赖文件：${relativePath}`);\n  }\n  return readFileSync(absolutePath, \"utf8\");\n}\n\nfunction trackedFiles(patterns) {\n  const result = spawnSync(\"git\", [\"ls-files\", \"--cached\", \"--others\", \"--exclude-standard\", \"--\", ...patterns], {\n    cwd: repositoryRoot,\n    encoding: \"utf8\",\n  });\n  if (result.status !== 0) {\n    fail(`无法读取 Git 文件清单：${result.stderr.trim()}`);\n  }\n  return result.stdout\n    .split(\"\\n\")\n    .filter(Boolean)\n    .filter((relativePath) => existsSync(pathFor(relativePath)));\n}\n\nfunction requireText(relativePath, expected, description) {\n  if (!read(relativePath).includes(expected)) {\n    fail(`${relativePath} 未满足${description}：${expected}`);\n  }\n}\n\n// 中文注释：构建与封装必须按固定顺序出现，避免只命中两个无关字符串却没有形成正式流程。\nfunction requireOrderedText(relativePath, expectedValues, description) {\n  const text = read(relativePath);\n  let offset = -1;\n  for (const expected of expectedValues) {\n    const next = text.indexOf(expected, offset + 1);\n    if (next < 0) fail(`${relativePath} 未满足${description}：${expected}`);\n    offset = next;\n  }\n}\n\nfunction escapeRegex(value) {\n  return value.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n}\n\nfunction exactCargoDependencyVersion(manifest, dependency) {\n  const tableMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\\\\{[^\\\\n}]*\\\\bversion\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const scalarMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const match = tableMatch ?? scalarMatch;\n  if (!match) {\n    fail(`citizenchain/node/Cargo.toml 必须准确固定 ${dependency}`);\n  }\n  return match[1];\n}\n\nfunction cargoLockPackageVersion(lock, packageName) {\n  const match = lock.match(new RegExp(\n    `\\\\[\\\\[package\\\\]\\\\]\\\\r?\\\\nname = \"${escapeRegex(packageName)}\"\\\\r?\\\\nversion = \"([^\"]+)\"`,\n  ));\n  if (!match) {\n    fail(`citizenchain/Cargo.lock 缺少 ${packageName}`);\n  }\n  return match[1];\n}\n\nfunction majorMinor(version, dependency) {\n  const match = version.match(/^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$/);\n  if (!match) {\n    fail(`${dependency} 不是规范三段版本：${version}`);\n  }\n  return `${match[1]}.${match[2]}`;\n}\n\nfunction checkTauri() {\n  const cargoManifest = read(\"citizenchain/node/Cargo.toml\");\n  const cargoLock = read(\"citizenchain/Cargo.lock\");\n  const npmManifest = JSON.parse(read(\"citizenchain/node/frontend/package.json\"));\n  const npmLock = JSON.parse(read(\"citizenchain/node/frontend/package-lock.json\"));\n  const rootPackage = npmLock.packages?.[\"\"];\n  const rustVersions = {\n    tauri: contract.tauri.core.rust,\n    \"tauri-build\": contract.tauri.build,\n    \"tauri-plugin-dialog\": contract.tauri.plugins.dialog,\n    \"tauri-plugin-process\": contract.tauri.plugins.process,\n    \"tauri-plugin-updater\": contract.tauri.plugins.updater,\n  };\n  const npmVersions = {\n    \"@tauri-apps/api\": contract.tauri.core.api,\n    \"@tauri-apps/cli\": contract.tauri.core.cli,\n    \"@tauri-apps/plugin-dialog\": contract.tauri.plugins.dialog,\n    \"@tauri-apps/plugin-process\": contract.tauri.plugins.process,\n    \"@tauri-apps/plugin-updater\": contract.tauri.plugins.updater,\n  };\n\n  for (const [dependency, expected] of Object.entries(rustVersions)) {\n    if (exactCargoDependencyVersion(cargoManifest, dependency) !== expected) {\n      fail(`citizenchain/node/Cargo.toml 的 ${dependency} 必须准确固定为 ${expected}`);\n    }\n    if (cargoLockPackageVersion(cargoLock, dependency) !== expected) {\n      fail(`citizenchain/Cargo.lock 的 ${dependency} 必须锁定为 ${expected}`);\n    }\n  }\n  for (const [dependency, expected] of Object.entries(npmVersions)) {\n    const manifestVersion = npmManifest.dependencies?.[dependency]\n      ?? npmManifest.devDependencies?.[dependency];\n    const rootVersion = rootPackage?.dependencies?.[dependency]\n      ?? rootPackage?.devDependencies?.[dependency];\n    const lockVersion = npmLock.packages?.[`node_modules/${dependency}`]?.version;\n    if (manifestVersion !== expected || rootVersion !== expected || lockVersion !== expected) {\n      fail(`citizenchain/node/frontend 的 ${dependency} 必须在 manifest 与 lockfile 准确固定为 ${expected}`);\n    }\n  }\n  for (const [packagePath, metadata] of Object.entries(npmLock.packages ?? {})) {\n    if (packagePath.startsWith(\"node_modules/@tauri-apps/cli-\")\n      && metadata.version !== contract.tauri.core.cli) {\n      fail(`${packagePath} 必须与 @tauri-apps/cli 同为 ${contract.tauri.core.cli}`);\n    }\n  }\n\n  const coreMinor = majorMinor(contract.tauri.core.rust, \"tauri\");\n  for (const [dependency, version] of [\n    [\"@tauri-apps/api\", contract.tauri.core.api],\n    [\"@tauri-apps/cli\", contract.tauri.core.cli],\n  ]) {\n    if (majorMinor(version, dependency) !== coreMinor) {\n      fail(`Tauri core 主次版本不一致：tauri=${contract.tauri.core.rust} ${dependency}=${version}`);\n    }\n  }\n\n  const cli = \"node frontend/node_modules/@tauri-apps/cli/tauri.js\";\n  for (const workflow of contract.scopes[\"citizenchain-node\"].workflows) {\n    const text = read(workflow);\n    if (text.includes(\"cargo install tauri-cli\") || /\\bcargo tauri\\b/.test(text)) {\n      fail(`${workflow} 仍依赖浮动或全局 Tauri CLI`);\n    }\n    if (!text.includes(`${cli} build --ci -- --locked`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 构建`);\n    }\n    if (workflow.includes(\"-release-\") && !text.includes(`${cli} signer sign`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 签名 updater`);\n    }\n  }\n  for (const script of [\"citizenchain/scripts/run.sh\", \"citizenchain/scripts/clean-run.sh\"]) {\n    if (/\\bcargo tauri\\b/.test(read(script))) {\n      fail(`${script} 仍依赖本机全局 Tauri CLI`);\n    }\n  }\n  const runScript = \"citizenchain/scripts/run.sh\";\n  requireOrderedText(runScript, [\n    `${cli} build --config \"$tauri_override\"`,\n    `--no-bundle --ci -- --locked`,\n    `${cli} bundle --config \"$tauri_override\"`,\n    `--bundles app --ci`,\n  ], \"仓库 Tauri CLI 正式编译与封装顺序\");\n  if (read(runScript).includes(`${cli} build --bundles app --ci`)) {\n    fail(`${runScript} 禁止恢复编译与封装合并的旧 Tauri 命令`);\n  }\n  requireText(\"citizenchain/scripts/clean-run.sh\", `${cli} dev -- --locked`, \"仓库 Tauri CLI 开发构建\");\n}\n\nfunction checkRequiredFiles(scope) {\n  for (const relativePath of scope.requiredFiles) {\n    read(relativePath);\n  }\n}\n\nfunction checkPackageLocks(projects) {\n  for (const directory of projects) {\n    const manifest = JSON.parse(read(`${directory}/package.json`));\n    const lock = JSON.parse(read(`${directory}/package-lock.json`));\n    const rootPackage = lock.packages?.[\"\"];\n    if (lock.lockfileVersion !== 3) {\n      fail(`${directory}/package-lock.json 必须使用 lockfileVersion 3`);\n    }\n    if (!rootPackage || rootPackage.name !== manifest.name) {\n      fail(`${directory} 的 package.json 与 package-lock.json 包名不一致`);\n    }\n    if (manifest.version && rootPackage.version !== manifest.version) {\n      fail(`${directory} 的 package.json 与 package-lock.json 版本不一致`);\n    }\n  }\n}\n\nfunction dartScalar(relativePath, dependency) {\n  const escaped = dependency.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const match = read(relativePath).match(new RegExp(`^  ${escaped}:\\\\s*([^#\\\\n]+?)\\\\s*$`, \"m\"));\n  if (!match) {\n    fail(`${relativePath} 缺少统一 Dart 依赖：${dependency}`);\n  }\n  return match[1].trim();\n}\n\nfunction checkSharedDartDependencies() {\n  for (const dependency of contract.sharedDartDependencies) {\n    const appVersion = dartScalar(\"citizenapp/pubspec.yaml\", dependency);\n    const walletVersion = dartScalar(\"citizenwallet/pubspec.yaml\", dependency);\n    if (appVersion !== walletVersion) {\n      fail(`移动端共享依赖 ${dependency} 版本不一致：CitizenApp=${appVersion} CitizenWallet=${walletVersion}`);\n    }\n  }\n}\n\nfunction checkToolchains(name) {\n  const { node, rust, flutter, java, gradle, androidNdk } = contract.toolchains;\n  const mobileScope = name === \"repository\" || [\"citizenapp\", \"citizensdk\", \"citizenwallet\"].includes(name);\n  const chainScope = name === \"repository\" || [\"citizenchain-node\", \"citizenchain-runtime\"].includes(name);\n  const nodeScope = name === \"repository\" || [\"citizenchain-node\", \"citizenserve\", \"citizenweb\"].includes(name);\n  if (mobileScope) {\n    majorMinor(flutter, \"Flutter\");\n  }\n  if (!/^\\d+(?:\\.\\d+){3}$/.test(androidNdk)) {\n    fail(`Android NDK 版本无效：${androidNdk}`);\n  }\n  const rustFiles = name === \"repository\"\n    ? [\"citizenchain/rust-toolchain.toml\", \"citizenapp/smoldot/ffi/rust-toolchain.toml\", \"citizensdk/native/smoldot/ffi/rust-toolchain.toml\"]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/smoldot/ffi/rust-toolchain.toml\"]\n      : name === \"citizensdk\"\n        ? [\"citizensdk/native/smoldot/ffi/rust-toolchain.toml\"]\n        : chainScope\n        ? [\"citizenchain/rust-toolchain.toml\"]\n        : [];\n  for (const file of rustFiles) {\n    requireText(file, `channel = \"${rust}\"`, \"Rust 版本统一契约\");\n  }\n  const nodeFiles = name === \"repository\"\n    ? [\"citizenchain/node/frontend/.nvmrc\", \"citizenweb/.nvmrc\"]\n    : name === \"citizenchain-node\"\n      ? [\"citizenchain/node/frontend/.nvmrc\"]\n      : name === \"citizenweb\"\n        ? [\"citizenweb/.nvmrc\"]\n        : [];\n  for (const file of nodeFiles) {\n    if (read(file).trim() !== node) {\n      fail(`${file} 必须精确固定 Node.js ${node}`);\n    }\n  }\n  const gradleFiles = name === \"repository\"\n    ? [\n        \"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\",\n        \"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\",\n      ]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\"]\n      : name === \"citizenwallet\"\n        ? [\"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\"]\n        : [];\n  for (const file of gradleFiles) {\n    requireText(file, `gradle-${gradle}-all.zip`, \"Gradle 版本统一契约\");\n  }\n  const workflows = name === \"repository\"\n    ? trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ])\n    : contract.scopes[name].workflows;\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/node-version:\\s*(?:['\"])?25(?:['\"])?\\s*$/m.test(text)) {\n      fail(`${workflow} 仍使用浮动 Node.js 25，必须精确固定 ${node}`);\n    }\n    if (nodeScope && text.includes(\"node-version:\") && !text.includes(`node-version: ${node}`)) {\n      fail(`${workflow} 的 Node.js 版本未统一为 ${node}`);\n    }\n    if (text.includes(\"java-version:\") && !text.includes(`java-version: ${java}`)) {\n      fail(`${workflow} 的 Java 版本未统一为 ${java}`);\n    }\n    if (workflow.includes(\"/citizensdk/\") && !text.includes(`ndk;${androidNdk}`)) {\n      fail(`${workflow} 的 Android NDK 版本未统一为 ${androidNdk}`);\n    }\n  }\n}\n\nfunction checkActions(workflows) {\n  for (const [action, sha] of Object.entries(contract.actions)) {\n    if (!shaPattern.test(sha)) {\n      fail(`${action} 未配置完整 commit SHA`);\n    }\n  }\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    for (const match of text.matchAll(/^\\s*uses:\\s*([^\\s#]+)(?:\\s+#.*)?$/gm)) {\n      const reference = match[1];\n      if (reference.startsWith(\"./\") || reference.startsWith(\"docker://\")) {\n        continue;\n      }\n      const separator = reference.lastIndexOf(\"@\");\n      const action = reference.slice(0, separator);\n      const revision = reference.slice(separator + 1);\n      if (!contract.actions[action]) {\n        fail(`${workflow} 使用了未登记 Action：${action}`);\n      }\n      if (revision !== contract.actions[action]) {\n        fail(`${workflow} 的 ${action} 未固定到统一 SHA ${contract.actions[action]}`);\n      }\n    }\n  }\n}\n\nfunction checkOfficialRunners(workflows) {\n  const allowed = new Set(contract.officialRunners);\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/runs-on:\\s*(?:\\[[^\\]]*\\bself-hosted\\b|\\bself-hosted\\b)/m.test(text)) {\n      fail(`${workflow} 使用了 self-hosted runner，必须使用统一官方镜像`);\n    }\n    const runnerLabels = [\n      ...text.matchAll(/^\\s*runs-on:\\s*((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)\\s*$/gm),\n      ...text.matchAll(/[\"']os[\"']\\s*:\\s*[\"']((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)[\"']/g),\n    ];\n    for (const match of runnerLabels) {\n      if (!allowed.has(match[1])) {\n        fail(`${workflow} 使用了未登记的 runner 镜像：${match[1]}`);\n      }\n    }\n  }\n}\n\nfunction checkGitDependencies(manifests) {\n  for (const manifest of manifests) {\n    const text = read(manifest);\n    if (/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\b(branch|tag)\\s*=/m.test(text)) {\n      fail(`${manifest} 存在可漂移的 Git branch/tag 依赖，必须使用 rev`);\n    }\n    for (const match of text.matchAll(/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\brev\\s*=\\s*\"([^\"]+)\"/g)) {\n      if (!shaPattern.test(match[1])) {\n        fail(`${manifest} 的 Git rev 不是完整 commit SHA：${match[1]}`);\n      }\n    }\n  }\n}\n\n// 中文注释：本地路径依赖必须从声明它的 manifest 目录解析；仅检查文件存在会漏掉\n// Cargo workspace 解析错误，因此全仓还会逐个执行 cargo metadata。\nfunction checkLocalDependencyPaths() {\n  const cargoManifests = trackedFiles([\"**/Cargo.toml\", \"Cargo.toml\"]);\n  for (const manifest of cargoManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    for (const match of read(manifest).matchAll(/\\bpath\\s*=\\s*\"([^\"]+)\"/g)) {\n      if (!existsSync(resolve(manifestDirectory, match[1]))) {\n        fail(`${manifest} 的 Cargo 本地依赖不存在：${match[1]}`);\n      }\n    }\n  }\n\n  const dartManifests = trackedFiles([\"**/pubspec.yaml\", \"pubspec.yaml\"]);\n  for (const manifest of dartManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    for (const match of read(manifest).matchAll(/^ {4}path:\\s*([^#\\n]+?)\\s*$/gm)) {\n      const dependencyPath = match[1].trim().replace(/^['\"]|['\"]$/g, \"\");\n      if (!existsSync(resolve(manifestDirectory, dependencyPath))) {\n        fail(`${manifest} 的 Dart 本地依赖不存在：${dependencyPath}`);\n      }\n    }\n  }\n\n  const npmManifests = trackedFiles([\"**/package.json\", \"package.json\"])\n    .filter((manifest) => !manifest.includes(\"/dist/\"));\n  for (const manifest of npmManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    const packageManifest = JSON.parse(read(manifest));\n    for (const dependencies of [\n      packageManifest.dependencies,\n      packageManifest.devDependencies,\n      packageManifest.optionalDependencies,\n    ]) {\n      for (const [dependency, version] of Object.entries(dependencies ?? {})) {\n        if (typeof version !== \"string\" || !version.startsWith(\"file:\")) continue;\n        const dependencyPath = version.slice(\"file:\".length);\n        if (!existsSync(resolve(manifestDirectory, dependencyPath))) {\n          fail(`${manifest} 的 npm 本地依赖 ${dependency} 不存在：${dependencyPath}`);\n        }\n      }\n    }\n  }\n}\n\nfunction checkCargoMetadata() {\n  for (const directory of contract.cargoProjects) {\n    console.log(`\\n[${directory}] cargo metadata --format-version 1 --locked --no-deps`);\n    const result = spawnSync(\n      \"cargo\",\n      [\"metadata\", \"--format-version\", \"1\", \"--locked\", \"--no-deps\"],\n      { cwd: pathFor(directory), encoding: \"utf8\" },\n    );\n    if (result.error) fail(`无法执行 cargo metadata：${result.error.message}`);\n    if (result.status !== 0) {\n      const detail = (result.stderr || result.stdout || \"\").trim();\n      fail(`${directory} 的 Cargo workspace 无法解析：${detail}`);\n    }\n  }\n}\n\nfunction workflowActionScript(workflow) {\n  if (workflow === '.github/workflows/gmb-repository.yml') {\n    return '.github/scripts/gmb-repository/ci-repository.mjs';\n  }\n  return workflow.replace(/^\\.github\\/workflows\\//, '.github/scripts/').replace(/\\.ya?ml$/, '.mjs');\n}\n\nfunction checkWorkflowScopes() {\n  const productWorkflows = [];\n  const expectedWorkflows = [];\n  const legacyName = `${\"gmb-ci\"}-repository.yml`;\n  for (const [name, scope] of Object.entries(contract.scopes)) {\n    for (const workflow of scope.workflows) {\n      expectedWorkflows.push(workflow);\n      const text = read(workflow);\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      if (!text.includes(invocation)) {\n        fail(`${workflow} 未调用依赖作用域：${name}`);\n      }\n      if (name !== \"repository\") {\n        productWorkflows.push(workflow);\n        if (text.includes(\"gmb-repository.yml\") || text.includes(legacyName)) {\n          fail(`${workflow} 不得调用或依赖仓库门禁`);\n        }\n      }\n    }\n  }\n  if (productWorkflows.length !== 24) {\n    fail(`产品 CI/Release workflow 必须精确为 24 条，当前契约登记 ${productWorkflows.length} 条`);\n  }\n  const actualWorkflows = trackedFiles([\n    \".github/workflows/*.yml\",\n    \".github/workflows/*.yaml\",\n    \".github/workflows/*/*.yml\",\n    \".github/workflows/*/*.yaml\",\n  ]);\n  const expected = [...expectedWorkflows].sort();\n  const actual = [...actualWorkflows].sort();\n  if (JSON.stringify(actual) !== JSON.stringify(expected)) {\n    fail(`workflow 清单与依赖契约不一致：期望 ${expected.length} 条，实际 ${actual.length} 条`);\n  }\n  const legacyWorkflow = `.github/workflows/${\"gmb-ci\"}-repository.yml`;\n  if (existsSync(pathFor(legacyWorkflow))) {\n    fail(`旧仓库门禁 ${legacyWorkflow} 仍存在`);\n  }\n}\n\nfunction checkFrozenCommands(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    for (const workflow of scope.workflows) {\n      const text = read(workflow);\n      if ([\"citizenapp\", \"citizensdk\", \"citizenwallet\"].includes(name) && !text.includes(\"flutter pub get --enforce-lockfile\")) {\n        fail(`${workflow} 未冻结 Flutter/Dart 应用依赖`);\n      }\n      if ([\"citizenserve\", \"citizenweb\"].includes(name) && !text.includes(\"npm ci\")) {\n        fail(`${workflow} 未使用 npm ci`);\n      }\n      if ([\"citizenchain-node\", \"citizenchain-runtime\", \"citizensdk\"].includes(name) && !text.includes(\"--locked\")) {\n        fail(`${workflow} 未冻结 Cargo 依赖`);\n      }\n    }\n  }\n}\n\nfunction checkAuditGates(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    const audited = contract.auditedScopes.includes(name);\n    const hasCargo = contract.cargoProjects.some((directory) =>\n      scope.requiredFiles.includes(projectFile(directory, \"Cargo.toml\")));\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies audit --scope ${name}`;\n      const text = read(workflow);\n      if (audited && !text.includes(invocation)) {\n        fail(`${workflow} 未接入已清零产品的阻断安全审计：${name}`);\n      }\n      if (!audited && text.includes(invocation)) {\n        fail(`${workflow} 接入了尚未登记零漏洞基线的安全审计：${name}`);\n      }\n      if (audited && hasCargo && !text.includes(\n        `cargo install cargo-audit --version ${contract.toolchains.cargoAudit} --locked`,\n      )) {\n        fail(`${workflow} 未安装固定版本 cargo-audit ${contract.toolchains.cargoAudit}`);\n      }\n    }\n  }\n}\n\nfunction checkScope(name) {\n  const scope = contract.scopes[name];\n  if (!scope) {\n    fail(`未知依赖作用域：${name}`);\n  }\n  checkRequiredFiles(scope);\n  if (name === \"repository\" || name === \"citizenchain-node\") {\n    checkTauri();\n  }\n  if (name === \"repository\") {\n    for (const candidate of Object.values(contract.scopes)) {\n      checkRequiredFiles(candidate);\n    }\n    checkPackageLocks(contract.npmProjects);\n    for (const directory of contract.dartApplications) {\n      read(`${directory}/pubspec.yaml`);\n      read(`${directory}/pubspec.lock`);\n    }\n    for (const directory of contract.cargoProjects) {\n      read(`${directory}/Cargo.toml`);\n      read(`${directory}/Cargo.lock`);\n    }\n    checkSharedDartDependencies();\n    checkToolchains(name);\n    const workflows = trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ]);\n    checkActions(workflows);\n    checkOfficialRunners(workflows);\n    checkGitDependencies(trackedFiles([\"**/Cargo.toml\", \"Cargo.toml\"]));\n    checkLocalDependencyPaths();\n    checkCargoMetadata();\n    checkWorkflowScopes();\n    checkFrozenCommands(Object.keys(contract.scopes));\n    checkAuditGates(Object.keys(contract.scopes));\n  } else {\n    checkPackageLocks(contract.npmProjects.filter((directory) =>\n      scope.requiredFiles.includes(`${directory}/package.json`)));\n    checkToolchains(name);\n    checkActions(scope.workflows);\n    checkOfficialRunners(scope.workflows);\n    checkGitDependencies(scope.requiredFiles.filter((file) => file.endsWith(\"Cargo.toml\")));\n    checkFrozenCommands([name]);\n    checkAuditGates([name]);\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      requireText(workflow, invocation, \"产品依赖作用域检查\");\n    }\n  }\n  console.log(`依赖检查通过：${name}`);\n}\n\nfunction projectFile(directory, fileName) {\n  return directory === \".\" ? fileName : `${directory}/${fileName}`;\n}\n\nfunction scopedProjects(projects, fileName) {\n  if (scopeName === \"repository\") {\n    return projects;\n  }\n  const requiredFiles = contract.scopes[scopeName]?.requiredFiles;\n  if (!requiredFiles) {\n    fail(`未知依赖作用域：${scopeName}`);\n  }\n  return projects.filter((directory) => requiredFiles.includes(projectFile(directory, fileName)));\n}\n\nfunction runNative(executable, argumentsValue, cwd, allowFailure = false) {\n  console.log(`\\n[${cwd}] ${executable} ${argumentsValue.join(\" \")}`);\n  const result = spawnSync(executable, argumentsValue, {\n    cwd: pathFor(cwd),\n    encoding: \"utf8\",\n    stdio: \"inherit\",\n  });\n  if (result.error) {\n    fail(`无法执行 ${executable}：${result.error.message}`);\n  }\n  if (result.status !== 0 && !allowFailure) {\n    fail(`${executable} 检查失败，退出码 ${result.status}`);\n  }\n}\n\nfunction audit() {\n  checkScope(scopeName);\n  const npmProjects = scopedProjects(contract.npmProjects, \"package.json\");\n  const cargoProjects = scopedProjects(contract.cargoProjects, \"Cargo.toml\");\n  for (const directory of npmProjects) {\n    runNative(\"npm\", [\"audit\", \"--audit-level=low\"], directory);\n  }\n  if (cargoProjects.length > 0) {\n    const auditVersion = spawnSync(\"cargo\", [\"audit\", \"--version\"], { encoding: \"utf8\" });\n    if (auditVersion.status !== 0 || !auditVersion.stdout.includes(contract.toolchains.cargoAudit)) {\n      fail(`cargo-audit 必须安装并固定为 ${contract.toolchains.cargoAudit}`);\n    }\n    for (const [index, directory] of cargoProjects.entries()) {\n      const argumentsValue = [\"audit\"];\n      if (index > 0) {\n        argumentsValue.push(\"--no-fetch\");\n      }\n      argumentsValue.push(\"--file\", projectFile(directory, \"Cargo.lock\"));\n      runNative(\"cargo\", argumentsValue, \".\");\n    }\n  }\n}\n\nfunction outdated() {\n  checkScope(scopeName);\n  for (const directory of scopedProjects(contract.npmProjects, \"package.json\")) {\n    runNative(\"npm\", [\"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.dartApplications, \"pubspec.yaml\")) {\n    runNative(\"dart\", [\"pub\", \"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.cargoProjects, \"Cargo.toml\")) {\n    runNative(\"cargo\", [\"update\", \"--dry-run\", \"--manifest-path\", projectFile(directory, \"Cargo.toml\")], \".\", true);\n  }\n  console.log(\"\\n过期版本仅报告；更新 manifest/lockfile 后必须重新执行产品真实验收。\");\n}\n\ntry {\n  if (contract.schema !== 1) {\n    fail(`不支持依赖契约 schema：${contract.schema}`);\n  }\n  if (command === \"check\") {\n    checkScope(scopeName);\n  } else if (command === \"audit\") {\n    audit();\n  } else if (command === \"outdated\") {\n    outdated();\n  } else {\n    fail(`未知命令：${command}`);\n  }\n} catch (error) {\n  console.error(`依赖检查失败：${error.message}`);\n  process.exitCode = 1;\n}\n","citizensdk-release":"#!/usr/bin/env node\n\n// CitizenSDK 确定性候选打包器。源码只读，所有候选和归档必须落在源码树之外。\nimport { createHash } from 'node:crypto';\nimport { gzipSync } from 'node:zlib';\nimport {\n  copyFileSync,\n  existsSync,\n  lstatSync,\n  mkdirSync,\n  readFileSync,\n  readdirSync,\n  writeFileSync,\n} from 'node:fs';\nimport { dirname, join, relative, resolve, sep } from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\nconst PRODUCT_ID = 'citizensdk';\nconst PACKAGE_NAME = 'citizen_sdk';\nconst CONSOLE_TARGET_ROOT = '/Users/rhett/Only/console/target/citizensdk';\nconst ROOT_FILES = [\n  '.gitignore',\n  'Cargo.lock',\n  'Cargo.toml',\n  'LICENSE-GPL-3.0',\n  'LICENSE-MIT',\n  'README.md',\n  'THIRD_PARTY_NOTICES.md',\n  'analysis_options.yaml',\n  'pubspec.lock',\n  'pubspec.yaml',\n];\nconst ROOT_DIRECTORIES = ['android', 'assets', 'docs', 'ios', 'lib', 'native', 'scripts', 'test'];\nconst FORBIDDEN_DIRECTORIES = new Set([\n  '.dart_tool', '.gradle', 'DerivedData', 'Pods', 'build', 'target',\n]);\nconst NATIVE_FILES = Object.freeze({\n  'android/src/main/jniLibs/arm64-v8a/libsmoldot.so': 'android/arm64-v8a/libsmoldot.so',\n  'ios/libsmoldot.a': 'ios/libsmoldot.a',\n  'ios/exported_symbols.txt': 'ios/exported_symbols.txt',\n});\n\nfunction fail(message) {\n  throw new Error(message);\n}\n\nfunction sha256File(path) {\n  return createHash('sha256').update(readFileSync(path)).digest('hex');\n}\n\nfunction stableJson(value) {\n  if (Array.isArray(value)) return `[${value.map(stableJson).join(',')}]`;\n  if (value && typeof value === 'object') {\n    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`).join(',')}}`;\n  }\n  return JSON.stringify(value);\n}\n\nfunction prettyStableJson(value) {\n  return `${JSON.stringify(JSON.parse(stableJson(value)), null, 2)}\\n`;\n}\n\nfunction assertOutsideSource(source, target, label) {\n  const sourcePrefix = `${resolve(source)}${sep}`;\n  const resolvedTarget = resolve(target);\n  if (resolvedTarget === resolve(source) || resolvedTarget.startsWith(sourcePrefix)) {\n    fail(`${label} 禁止位于 CitizenSDK 源码树：${resolvedTarget}`);\n  }\n}\n\nfunction assertLocalTarget(path, label) {\n  if (process.env.GITHUB_ACTIONS === 'true') return;\n  const root = resolve(CONSOLE_TARGET_ROOT);\n  const target = resolve(path);\n  if (target !== root && !target.startsWith(`${root}${sep}`)) {\n    fail(`${label} 的本地路径必须位于 ${root}：${target}`);\n  }\n}\n\nfunction ensureNewDirectory(path, source, label) {\n  assertOutsideSource(source, path, label);\n  if (existsSync(path)) fail(`${label} 已存在，拒绝覆盖：${path}`);\n  mkdirSync(path, { recursive: true, mode: 0o700 });\n}\n\nfunction copySourceTree(source, output, relativePath) {\n  const sourcePath = join(source, ...relativePath.split('/'));\n  const info = lstatSync(sourcePath);\n  if (info.isSymbolicLink()) fail(`SDK 候选禁止符号链接：${relativePath}`);\n  if (info.isDirectory()) {\n    if (FORBIDDEN_DIRECTORIES.has(relativePath.split('/').at(-1))) {\n      fail(`SDK 源码包含编译目录：${relativePath}`);\n    }\n    mkdirSync(join(output, ...relativePath.split('/')), { recursive: true, mode: 0o700 });\n    for (const name of readdirSync(sourcePath).sort()) {\n      copySourceTree(source, output, `${relativePath}/${name}`);\n    }\n    return;\n  }\n  if (!info.isFile()) fail(`SDK 候选只允许普通文件和目录：${relativePath}`);\n  if (/\\.(?:a|dylib|dll|exe|o|so)$/i.test(relativePath) || relativePath.endsWith('/exported_symbols.txt')) {\n    fail(`SDK 源码树包含原生编译产物：${relativePath}`);\n  }\n  const destination = join(output, ...relativePath.split('/'));\n  mkdirSync(dirname(destination), { recursive: true, mode: 0o700 });\n  copyFileSync(sourcePath, destination);\n}\n\nfunction regularFiles(root) {\n  const files = [];\n  const visit = (directory) => {\n    for (const name of readdirSync(directory).sort()) {\n      const path = join(directory, name);\n      const info = lstatSync(path);\n      const relativePath = relative(root, path).split(sep).join('/');\n      if (info.isSymbolicLink()) fail(`SDK 候选禁止符号链接：${relativePath}`);\n      if (info.isDirectory()) visit(path);\n      else if (info.isFile()) files.push(relativePath);\n      else fail(`SDK 候选只允许普通文件和目录：${relativePath}`);\n    }\n  };\n  visit(root);\n  return files.sort();\n}\n\nfunction replaceExact(path, pattern, replacement, label) {\n  const source = readFileSync(path, 'utf8');\n  const matches = source.match(pattern);\n  if (!matches || matches.length !== 1) fail(`${label} 版本字段不唯一`);\n  writeFileSync(path, source.replace(pattern, replacement));\n}\n\nfunction applySoftwareVersion(output, version) {\n  replaceExact(join(output, 'pubspec.yaml'), /^version: \\d+\\.\\d{1,2}\\.\\d{1,2}$/gm, `version: ${version}`, 'pubspec.yaml');\n  replaceExact(join(output, 'android/build.gradle'), /^version = '\\d+\\.\\d{1,2}\\.\\d{1,2}'$/gm, `version = '${version}'`, 'android/build.gradle');\n  replaceExact(join(output, 'ios/citizen_sdk.podspec'), /^  s\\.version\\s+= '\\d+\\.\\d{1,2}\\.\\d{1,2}'$/gm, `  s.version          = '${version}'`, 'citizen_sdk.podspec');\n}\n\nfunction copyNativeFiles(nativeRoot, output) {\n  for (const [destinationPath, sourcePath] of Object.entries(NATIVE_FILES)) {\n    const source = join(nativeRoot, ...sourcePath.split('/'));\n    if (!existsSync(source) || !lstatSync(source).isFile()) fail(`缺少原生产物：${sourcePath}`);\n    const destination = join(output, ...destinationPath.split('/'));\n    mkdirSync(dirname(destination), { recursive: true, mode: 0o700 });\n    copyFileSync(source, destination);\n  }\n}\n\nfunction assertNoSecrets(root) {\n  const forbiddenName = /(^|\\/)(\\.env(?:\\.|$)|\\.dev\\.vars(?:\\.|$)|.*\\.(?:jks|keystore|p8|p12|pem))$/i;\n  const privateMaterial = Buffer.from('PRIVATE KEY-----');\n  for (const relativePath of regularFiles(root)) {\n    if (forbiddenName.test(relativePath)) fail(`SDK 候选包含禁止的本地或密钥文件：${relativePath}`);\n    if (readFileSync(join(root, ...relativePath.split('/'))).includes(privateMaterial)) {\n      fail(`SDK 候选疑似包含私钥材料：${relativePath}`);\n    }\n  }\n}\n\nfunction fileEntries(root, paths) {\n  return paths.map((path) => ({ path, sha256: sha256File(join(root, ...path.split('/'))) }));\n}\n\nfunction writeOctal(buffer, offset, length, value) {\n  const text = value.toString(8).padStart(length - 1, '0');\n  if (text.length >= length) fail('CitizenSDK 归档字段超过 tar 限制');\n  buffer.write(`${text}\\0`, offset, length, 'ascii');\n}\n\nfunction deterministicTar(candidatePath) {\n  const chunks = [];\n  for (const relativePath of regularFiles(candidatePath)) {\n    if (Buffer.byteLength(relativePath) > 100) fail(`CitizenSDK 归档路径过长：${relativePath}`);\n    const path = join(candidatePath, ...relativePath.split('/'));\n    const content = readFileSync(path);\n    const header = Buffer.alloc(512);\n    header.write(relativePath, 0, 100, 'utf8');\n    writeOctal(header, 100, 8, (lstatSync(path).mode & 0o111) === 0 ? 0o600 : 0o700);\n    writeOctal(header, 108, 8, 0);\n    writeOctal(header, 116, 8, 0);\n    writeOctal(header, 124, 12, content.length);\n    writeOctal(header, 136, 12, 0);\n    header.fill(0x20, 148, 156);\n    header[156] = '0'.charCodeAt(0);\n    header.write('ustar\\0', 257, 6, 'ascii');\n    header.write('00', 263, 2, 'ascii');\n    const checksum = header.reduce((sum, byte) => sum + byte, 0);\n    header.write(`${checksum.toString(8).padStart(6, '0')}\\0 `, 148, 8, 'ascii');\n    chunks.push(header, content);\n    const padding = (512 - (content.length % 512)) % 512;\n    if (padding) chunks.push(Buffer.alloc(padding));\n  }\n  chunks.push(Buffer.alloc(1024));\n  return Buffer.concat(chunks);\n}\n\nexport function verifyCitizenSdkRelease(candidatePath, expectedGitSha = null) {\n  const candidate = resolve(candidatePath);\n  if (!existsSync(candidate) || lstatSync(candidate).isSymbolicLink() || !lstatSync(candidate).isDirectory()) {\n    fail('CitizenSDK 候选目录不存在或不是普通目录');\n  }\n  const manifestPath = join(candidate, 'citizensdk-release.json');\n  const sumsPath = join(candidate, 'SHA256SUMS');\n  if (!existsSync(manifestPath) || !existsSync(sumsPath)) fail('CitizenSDK 候选缺少正式清单');\n  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));\n  const keys = Object.keys(manifest).sort();\n  const expectedKeys = ['files', 'git_commit_sha', 'package_name', 'platforms', 'product_id', 'software_version'];\n  if (JSON.stringify(keys) !== JSON.stringify(expectedKeys)) fail('CitizenSDK 正式清单字段集合不正确');\n  if (manifest.product_id !== PRODUCT_ID || manifest.package_name !== PACKAGE_NAME) fail('CitizenSDK 候选产品身份不正确');\n  if (!/^\\d+\\.\\d{1,2}\\.\\d{1,2}$/.test(manifest.software_version)) fail('CitizenSDK 候选版本无效');\n  if (!/^[0-9a-f]{40}$/.test(manifest.git_commit_sha)) fail('CitizenSDK 候选 Git SHA 无效');\n  if (expectedGitSha !== null && manifest.git_commit_sha !== expectedGitSha) fail('CitizenSDK 候选 Git SHA 不匹配');\n  const expectedPlatforms = [\n    { abi: 'arm64-v8a', platform: 'android' },\n    { abi: 'arm64', platform: 'ios' },\n  ];\n  if (stableJson(manifest.platforms) !== stableJson(expectedPlatforms)) fail('CitizenSDK 候选平台集合不正确');\n  if (!Array.isArray(manifest.files) || manifest.files.length === 0) fail('CitizenSDK 候选文件清单为空');\n  const paths = [];\n  for (const entry of manifest.files) {\n    if (!entry || Object.keys(entry).sort().join(',') !== 'path,sha256'\n        || typeof entry.path !== 'string' || entry.path.startsWith('/')\n        || entry.path.split('/').includes('..') || !/^[A-Za-z0-9._/-]+$/.test(entry.path)\n        || !/^[0-9a-f]{64}$/.test(entry.sha256)) {\n      fail('CitizenSDK 候选文件条目无效');\n    }\n    const path = join(candidate, ...entry.path.split('/'));\n    if (!path.startsWith(`${candidate}${sep}`)) fail('CitizenSDK 候选文件路径越界');\n    if (!existsSync(path) || !lstatSync(path).isFile() || sha256File(path) !== entry.sha256) {\n      fail(`CitizenSDK 候选文件哈希不一致：${entry.path}`);\n    }\n    paths.push(entry.path);\n  }\n  if (JSON.stringify(paths) !== JSON.stringify([...paths].sort()) || new Set(paths).size !== paths.length) {\n    fail('CitizenSDK 候选文件顺序或唯一性无效');\n  }\n  for (const required of ['pubspec.yaml', ...Object.keys(NATIVE_FILES)]) {\n    if (!paths.includes(required)) fail(`CitizenSDK 候选缺少必需文件：${required}`);\n  }\n  const checksums = [\n    ...manifest.files,\n    { path: 'citizensdk-release.json', sha256: sha256File(manifestPath) },\n  ].sort((left, right) => left.path.localeCompare(right.path));\n  const expectedSums = `${checksums.map(({ sha256, path }) => `${sha256}  ${path}`).join('\\n')}\\n`;\n  if (readFileSync(sumsPath, 'utf8') !== expectedSums) fail('CitizenSDK SHA256SUMS 不一致');\n  const expectedFiles = [...paths, 'SHA256SUMS', 'citizensdk-release.json'].sort();\n  if (JSON.stringify(regularFiles(candidate)) !== JSON.stringify(expectedFiles)) fail('CitizenSDK 候选包含未登记文件');\n  assertNoSecrets(candidate);\n  return manifest;\n}\n\nexport function buildCitizenSdkRelease({ sourcePath, nativePath, outputPath, archivePath, gitCommitSha, softwareVersion }) {\n  const source = resolve(sourcePath);\n  const native = resolve(nativePath);\n  const output = resolve(outputPath);\n  const archive = resolve(archivePath);\n  if (!existsSync(source) || !lstatSync(source).isDirectory()) fail('CitizenSDK 源码目录不存在');\n  if (!existsSync(native) || !lstatSync(native).isDirectory()) fail('CitizenSDK 原生产物目录不存在');\n  if (!/^[0-9a-f]{40}$/.test(gitCommitSha)) fail('Git commit SHA 必须是 40 位小写十六进制');\n  if (!/^\\d+\\.\\d{1,2}\\.\\d{1,2}$/.test(softwareVersion)) fail('CitizenSDK 软件版本无效');\n  assertLocalTarget(native, '原生产物目录');\n  assertLocalTarget(output, '候选目录');\n  assertLocalTarget(archive, '归档');\n  assertOutsideSource(source, native, '原生产物目录');\n  assertOutsideSource(source, archive, '归档');\n  assertOutsideSource(native, output, '候选目录');\n  assertOutsideSource(output, archive, '归档');\n  if (existsSync(archive)) fail(`归档已存在，拒绝覆盖：${archive}`);\n  ensureNewDirectory(output, source, '候选目录');\n  for (const path of ROOT_FILES) copySourceTree(source, output, path);\n  for (const path of ROOT_DIRECTORIES) copySourceTree(source, output, path);\n  applySoftwareVersion(output, softwareVersion);\n  copyNativeFiles(native, output);\n  const payloadPaths = regularFiles(output);\n  const manifest = {\n    product_id: PRODUCT_ID,\n    package_name: PACKAGE_NAME,\n    software_version: softwareVersion,\n    git_commit_sha: gitCommitSha,\n    platforms: [\n      { platform: 'android', abi: 'arm64-v8a' },\n      { platform: 'ios', abi: 'arm64' },\n    ],\n    files: fileEntries(output, payloadPaths),\n  };\n  const manifestPath = join(output, 'citizensdk-release.json');\n  writeFileSync(manifestPath, prettyStableJson(manifest), { mode: 0o600 });\n  const checksums = [\n    ...manifest.files,\n    { path: 'citizensdk-release.json', sha256: sha256File(manifestPath) },\n  ].sort((left, right) => left.path.localeCompare(right.path));\n  writeFileSync(join(output, 'SHA256SUMS'), `${checksums.map(({ sha256, path }) => `${sha256}  ${path}`).join('\\n')}\\n`, { mode: 0o600 });\n  verifyCitizenSdkRelease(output, gitCommitSha);\n  mkdirSync(dirname(archive), { recursive: true, mode: 0o700 });\n  writeFileSync(archive, gzipSync(deterministicTar(output), { level: 9, mtime: 0 }), { mode: 0o600 });\n  return manifest;\n}\n\nfunction parseArguments(argumentsList) {\n  const values = {};\n  for (let index = 0; index < argumentsList.length; index += 2) {\n    const key = argumentsList[index];\n    const value = argumentsList[index + 1];\n    if (!key?.startsWith('--') || value === undefined) fail(`参数格式无效：${key || ''}`);\n    values[key.slice(2)] = value;\n  }\n  return values;\n}\n\nconst isMain = process.argv[1] && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url));\nif (isMain) {\n  try {\n    const values = parseArguments(process.argv.slice(2));\n    if (values.verify) {\n      const manifest = verifyCitizenSdkRelease(values.verify, values['expected-git-sha'] || null);\n      process.stdout.write(`CitizenSDK 候选校验通过：${manifest.software_version}\\n`);\n    } else {\n      for (const key of ['source', 'native', 'output', 'archive', 'git-sha', 'software-version']) {\n        if (!values[key]) fail(`缺少参数 --${key}`);\n      }\n      const manifest = buildCitizenSdkRelease({\n        sourcePath: values.source,\n        nativePath: values.native,\n        outputPath: values.output,\n        archivePath: values.archive,\n        gitCommitSha: values['git-sha'],\n        softwareVersion: values['software-version'],\n      });\n      process.stdout.write(`CitizenSDK 候选已生成：${manifest.software_version}\\n`);\n    }\n  } catch (error) {\n    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\\n`);\n    process.exitCode = 1;\n  }\n}\n"});
const [command, ...argumentsList] = process.argv.slice(2);
if (!command || !Object.hasOwn(implementations, command)) {
  console.error(`未登记动作子命令：${command || '(empty)'}；允许值：${Object.keys(implementations).join(', ')}`);
  process.exit(2);
}
const temporaryDirectory = mkdtempSync(join(tmpdir(), 'gmb-action-'));
const shellCommand = command === 'linux-deps' || command === 'guardrails';
const implementationPath = join(temporaryDirectory, shellCommand ? 'implementation.sh' : 'implementation.mjs');
try {
  writeFileSync(implementationPath, implementations[command], { mode: 0o700 });
  const result = spawnSync(shellCommand ? '/bin/bash' : process.execPath, [realpathSync(implementationPath), ...argumentsList], {
    cwd: repositoryRoot,
    env: { ...process.env, GMB_REPOSITORY_ROOT: repositoryRoot },
    stdio: 'inherit',
  });
  if (result.error) throw result.error;
  process.exitCode = result.status ?? 1;
} finally {
  rmSync(temporaryDirectory, { recursive: true, force: true });
}
